import{_ as o,C as r,o as a,c as n,j as e,a as s,E as l,a5 as i}from"./chunks/framework.DNkHA0lr.js";const _=JSON.parse('{"title":"如何比 99% 的人更高效 & 如何走出低谷","description":"","frontmatter":{"title":"如何比 99% 的人更高效 & 如何走出低谷","originalTitle":"How To Be More Productive Than 99% Of People & How To Get Out Of A Rut","date":"2023-09-16","originalUrl":"https://thedankoe.com/letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut/","minutes":12,"sourceHash":"f782905a96e238607003ac27922639850f0b89b350b9041dc83366550d65309f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut/"}]]},"headers":[],"relativePath":"letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut.md","filePath":"letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut.md"}'),h={name:"letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut.md"};function c(f,p,u,d,g,m){const t=r("ArticleMeta");return a(),n("div",null,[p[0]||(p[0]=e("h1",{id:"如何比-99-的人更高效-如何走出低谷",tabindex:"-1"},[s("如何比 99% 的人更高效 & 如何走出低谷 "),e("a",{class:"header-anchor",href:"#如何比-99-的人更高效-如何走出低谷","aria-label":'Permalink to "如何比 99% 的人更高效 & 如何走出低谷"'},"​")],-1)),l(t),p[1]||(p[1]=i('<p><a href="https://www.youtube.com/embed/XV5-PHwzubY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我做过的最好的决定，往往是别人眼中“愚蠢”的决定。</p><p><strong>2018年：</strong></p><p>我挥霍了毕生积蓄，刷爆了第一张信用卡，只为了努力让一门生意运转起来。</p><p><strong>2019年：</strong></p><p>我处理掉了我拥有的所有东西（除了几袋衣服和一台笔记本电脑），飞去了一个陌生的国家。</p><p>我还辞掉了工作，尽管当时我的自由职业生意随时可能在一瞬间失去所有的客户。</p><p><strong>2020年：</strong></p><p>我签下了一套公寓的租约，租金是我能负担得起的两倍。</p><p>这逼着我必须把生意做成。</p><p><strong>从2021年至今：</strong></p><p>我每六个月就搬一次家。</p><p>每一次搬家都比上一次开销更大，迫使我的收入也随之增长，因为在数字世界里，唯一的限制就是你深信不疑的那些限制。</p><p>我的收入年复一年地从每月 50,000 美元、100,000 美元涨到了 200,000 美元。</p><p>很难将这一切归功于某一条商业建议或某一本书。</p><p>我清楚我的进步，源于我不允许自己陷入停滞和分心的黑洞。</p><p>我和 JK·莫利纳 (JK Molina)、达科塔·罗伯逊 (Dakota Robertson) 以及我的编辑德文 (Devan) 一起搬到了得克萨斯州奥斯汀 (Austin, Texas)。这极大地改变了我看待线上业务的方式。</p><p>我一时兴起又搬回了亚利桑那州斯科茨代尔 (Scottsdale, Arizona)。我们违约退租，把我们仅有的 10 件左右的物品扔进我的车里，在下一个租期开始前，在酒店里住了 2 个星期。</p><p>我现在住在菲尼克斯 (Phoenix)，但我又心痒痒想搬家了，所以我打算在未来两周内搬走。随着新书和软件发布的临近，我需要给自己的系统来一次电击，把自己狠狠抛向未知。</p><p>那是我茁壮成长的地方，但前提是我得有能力接受这种挑战。</p><p><strong>更新：</strong>我是在周五开始写这篇文章的，今天是周一，我的入住日期是明天（周二）。租约在周六就撕毁了 🙂</p><p>现在，我的生活质量、灵感产出和多巴胺水平都在飙升。</p><p>一切都变得充满意义，因为我肩负着如此多的责任，以至于所有的信息都可以被付诸实践。</p><p>如果生活让人觉得毫无意义，那是因为你没有在锻炼你的“责任感肌肉”。</p><p>你还没有举起足够的情绪重量，去在杠铃上增加更多的杠铃片，并在比肌肉更深的层次上看到进步。</p><h2 id="战术性压力-tactical-stress-——-异常结果背后的秘密" tabindex="-1">战术性压力 (Tactical Stress) —— 异常结果背后的秘密 <a class="header-anchor" href="#战术性压力-tactical-stress-——-异常结果背后的秘密" aria-label="Permalink to &quot;战术性压力 (Tactical Stress) —— 异常结果背后的秘密&quot;">​</a></h2><p>金鱼会根据你把它放在多大的鱼缸里来决定长多大。</p><p>但如果你一直把它们养在一个小碗里，它们就永远长不大。</p><p>有一个类似的现象，可以用帕金森定律 (Parkinson&#39;s Law) 来解释：</p><p>“工作会不断膨胀，直到填满分配给它完成的时间。”</p><p>我所说的“战术性压力”与之非常相似：</p><blockquote><p>战术性压力是指有意识地决定将自己逼入孤注一掷的境地——你深知自己有能力应对——而且除了克服恐惧别无选择。其结果是一段高强度的时期，它将推动你进入人生的下一个阶段。</p></blockquote><p>当你理解了这个概念，你就会把它作为一种工具加入到你的思维工具带中。</p><p>当你发现自己陷入低谷时，你就可以用这个工具逼迫自己挖出一条生路。</p><p>这里有一些应用和策略，你可以拿来作为灵感：</p><h3 id="战术性压力的哲学与心理学" tabindex="-1">战术性压力的哲学与心理学 <a class="header-anchor" href="#战术性压力的哲学与心理学" aria-label="Permalink to &quot;战术性压力的哲学与心理学&quot;">​</a></h3><p>每次我利用战术性压力打破低谷时，随之而来的总是一段极度高效的时期。</p><p>除了工作，我什么都不会做。</p><p>这是我为数不多打破“每天工作 4 小时”原则的时候。我会长时间工作，并且享受其中的每一秒。</p><p>有趣的是，这些时期也是我最具创造力的时期。</p><p>通常来说，生产力和创造力存在于一个光谱的两个极端。</p><p>但这里有一种“物极必反”（走向闭环）的主题，两端坍缩合二为一，这通常意味着进入了高度的心流 (flow) 状态。</p><p><strong>走向闭环 (Going Full Circle)</strong></p><p>想象一条直线，一端是黑色，另一端是白色，中间是让它们融合在一起的渐变色。</p><p>这条线可以代表生活中的大多数事物，因为没有任何事情是绝对非黑即白的。</p><p>万事万物都存在于光谱之上。一切都是相对的。一切都只是一种心态或意识状态。</p><p>能量、生产力、创造力、智力、愤怒、悲伤、快乐、平静、压力、咸、甜、粗糙、柔软、明亮和黑暗，这些都存在着 <em>程度</em> 的区别。</p><p>所有这些融合在一起，创造了你生而为人的体验。</p><p>它们并不局限于某一种，而是可以通过你的意识将它们剥离出来。你可以拆解你当前的心境，并探索其深度。</p><p>现在，想象一下之前那条从黑到白的渐变线。</p><p>但现在，把两端连起来，让它形成一个圆。</p><p>黑色现在瞬间翻转成了白色。</p><p>相比起有两端死胡同的直线，这是一个对生活、或是对你心态更准确的体现。</p><p>这种翻转和颜色代表了“走向闭环”的现象。</p><p>当一个人蠢到极致时，他就会变聪明（大智若愚）。</p><p>当一个人无趣到极致时，他反而变得搞笑了。</p><p>当一个人疲惫到极致时，他反而会变得精力充沛。</p><p>黑白两端交汇的地方，就是战术性压力发挥作用的地方。在那个点上，你有意识地将现实的某些方面推向极限，然后看着它向有利于你的方向反弹。</p><p><strong>战术性压力的心理学</strong></p><p>战术性压力的目的是将你自己发射到未知之中——那是一片拥有无限潜力的土地。</p><p>你会被海量的信息淹没。</p><p>你的大脑根本来不及消化这些信息。</p><p>因此，你被迫在混乱中创造清晰。</p><p>你设定一个近乎不可能的目标，逼迫自己去实现它，并把压力转化为拼命（your a** off）学习和行动的动力，直到它变成现实。</p><p>这样做能带来几点好处。</p><p><strong>首先</strong>，它建立了一个参考框架。</p><p>当你冲向未知时，你的目标必须保持在首位。你的目标是你从噪音中过滤信号的方式。你的目标是你如何在淹没大脑的混乱信息中发现机会的方式。</p><p>如果你逼着自己横跨全国搬家并成为一名数字游民，你会发现某些信息对于实现那个目标更加有用。</p><p>你会自然而然地注意到特定的社交媒体帖子，关注新的账号，并开始给你的大脑编程以执行特定的行动。</p><p><strong>其次</strong>，它设定了一个最后期限 (deadline)。</p><p>大家都知道，最后期限对于提高生产力非常有效。但大多数的期限都不是<em>真正的</em>期限。</p><p>当你飞越整个国家，或者把毕生积蓄投资在教练辅导上时，这个期限就再真实不过了。</p><p>你要么把事情做成，要么让自己崩溃，因为你的生存受到了威胁。</p><p>战术性压力让你暂时处于一种求生模式。</p><p>这确实不健康，但它是暂时的。</p><p><strong>第三</strong>，它收窄了你的专注力。</p><p>当你的心思全放在目标上时，分心的事情就无法穿透你的框架。</p><p>它是你唯一能关注的事情。</p><p>你睡觉前都在想它。</p><p>你的大脑会不停地制定计划，好让你摆脱目前的困境。</p><p>而一旦你通过学习和行动理清了你必须做什么，你就能利用那种如同激光般的专注力去构建任何必要的东西，从而实现目标。</p><p><strong>打破你的金钱限制</strong></p><p>可以肯定地说，如果你想在生活中继续向前推进，在某个时刻你就必须得创业。</p><p>我之所以能一次又一次地做到这一点，唯一的原因就是我拥有自己的生意。</p><p>一门生意给了你创造性的边界，让你可以随心所欲地增加收入。这在任何工作岗位上都是不可能的。我才不在乎那个花了 40 年时间爬上高位拿高薪的 CEO，因为我只需花 2-6 年的时间专注打造我自己的事业就能实现这个目标。</p><p>战术性压力是我逼迫生意增长的方法。</p><p>当我搬家横跨全国或投资了我一生的积蓄时，这创造出了对更多金钱的需求。</p><p>如果我没有生意，我就无法如此快速地增加收入。想靠跳槽多赚 100,000 美元，得花上好几年的时间。</p><p>在商业中，要实现这一目标，我所需要的只是一个恰当的策略、合适的技能包、一个不可抗拒的报价 (offer)，以及足够的流量来卖出价值 100,000 美元的产品。是的，我知道这是在过度简化，但这并不意味着它是错的，或者不值得一听。</p><p>打造你自己的事业。</p><h2 id="战术性压力策略" tabindex="-1">战术性压力策略 <a class="header-anchor" href="#战术性压力策略" aria-label="Permalink to &quot;战术性压力策略&quot;">​</a></h2><p>回顾我的生活，以下就是我做过的一些算得上是战术性压力的行为。</p><p>这些并不是唯一的方法，但它们可以作为灵感。</p><p>你们当中的很多人拥有创作者 (creator) 事业（或者至少正在努力打造一个），而下面其中一项可能正是你需要的推力。</p><p><strong>1) 在构建产品之前先发售它。</strong></p><p>新手认为你需要先有一款产品或服务，然后才能开始销售。</p><p>这种做法是最愚蠢的。</p><p>你甚至都不知道这个想法是否已经得到了验证。</p><p>相反，你应该先创建报价 (offer) 和落地页。</p><p>设定一个 3-4 周后的发布日期。这就是你的最后期限。</p><p>开始大力推广，往死里推。</p><p>显然，这需要你具备相关知识和技能——知道如何建立受众群体，以及如何打造引人注目的产品或服务。</p><p>我建议你去 YouTube 上观看我的 <a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4&amp;si=g7OPBdwyH__-Qp6Y" target="_blank" rel="noreferrer">一人企业 (One Person Business) 播放列表</a>，或者，如果你想直接获取我毫无保留的所有系统，可以报名 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics (数字经济学)</a>。</p><p>一旦你有了一个买家，压力就来了。</p><p>你要么在破纪录的时间内创造出 MVP (最小可行性产品)，要么你不仅失败，还得退还所有你赚到的钱。</p><p><strong>2) 不断变换居住地 (Location hopping)。</strong></p><p>我并不是有意为之，但在过去的两年里，我发现自己每 6 个月就会搬一次家。</p><p>主要是因为我觉得自己已经在这个地方探索尽了一切。</p><p>我摸透了所有的餐厅。我走遍了所有的散步小径。我清楚自己还能在朋友圈里添些什么样的新朋友。</p><p>再也没有进一步探索的空间了。</p><p>所以，当事情开始变得单调乏味时，我就搬走了。</p><p>这一点在创业与打工的对比中也同样适用。</p><p>创业让你时刻保持警惕。如果你停滞不前，那是你自己的错。你有权选择将规模扩大到你想要的任何高度，而个人发展将被迫紧随其后。</p><p>每次搬家时，我总是努力提高我所处环境的质量。</p><p>更好的人脉网络。</p><p>更好的资源。</p><p>更好的步行体验。</p><p>更方便的美食选择。</p><p>当然，这是有代价的。这便是战术性压力发挥作用的地方。</p><p>我会签下一套公寓的租约，那种感觉就像是站在舒适区的边缘试探。</p><p>那是我能负担得起的价格，但我必须增加收入，才能缓解更高昂的租金带来的压力。</p><p>生存，是一个强效的短期生产力工具。</p><p><strong>3) 投资教育。</strong></p><p>我以前是个课程囤积狂。</p><p>在我的整个职业旅程中，我购买了至少 50 门社交媒体、Web 开发、自由职业和营销相关的课程。</p><p>它们帮我积累了知识，但还不足以促使我采取行动。</p><p>在自由职业网页设计方面取得了一些成功之后，我确信自己想要全身心投入 (go all in) 到社交媒体上。</p><p>我看到了在自己的一生中，能够无限期建立起读者群的潜力。</p><p>我发现，用有价值的写作（他们想读的）建立受众，能让我打造和销售任何我想卖的东西来谋生——只要客户也想要。</p><p>这就是我创建 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 背后的驱动力。为了传递数字文字的力量。</p><p>我做了什么？</p><p>我花了 3500 美元买了一个辅导项目。</p><p>那让我的心理账户感觉很不好受。</p><p>结果发生了什么？</p><p>我只参加了一次辅导通话。</p><p>就一次。</p><p>但这足以向我证明，我已经知道自己该做什么了。</p><p>创作内容，结交在线社会地位高的朋友让内容被分享，并不断迭代产品或服务，直到我挖到金矿。</p><p>在这个项目上的投资迫使我开始做我现在所做的事情，并且永不放弃。</p><p><strong>4) 物质物品。</strong></p><p>这是一个敏感话题。</p><p>我不是一个非常物质的人。</p><p>我现在确确实实是在我的客厅里写下这段话的，这里除了书桌什么都没有。没有沙发，没有电视，什么都没有。只有一张用来写作的桌子。</p><p>但是，物质物品也有它们的好处。</p><p>其中之一就是它们能彰显地位。</p><p>当然，你可能不想玩地位游戏，但每个人都会以貌取人。</p><p>那辆车、那块表或那件衬衫，可能就是让某人想给你一个百万美元机会的潜意识决定因素。</p><p>我开着一辆相当不错的车。</p><p>（如果有人好奇，那是一辆梅赛德斯 GT63s——当然是哑光黑的，以契合我的品牌形象）。</p><p>当我走向它时，人们递给我的名片数量简直疯狂。这种关注有点烦人，但你无法否认这带来了社会地位的提升。</p><p>只是别让物质主义吞噬了你。</p><p>如果情况需要，我随时准备把它卖掉，甚至直接舍弃。</p><p>当我全款买下那辆车时，那可是掏空了我钱包里的一大块。</p><p>凭借我长期积累的杠杆，在一周内构建、推销并发布一项新报价（offer）把那笔钱赚回来，这几乎成了一种本能。</p><p><strong>5) 堕落。</strong></p><p>另一个敏感话题。</p><p>对所有这些事情来说，都有明显的界限是你可能会越过的。</p><p>战术性压力不适合无脑之人。</p><p>我也不喜欢去粉饰那些帮助了我个人成长，却经常被禁欲系的 Huberman（休伯曼）狂热信徒妖魔化的事情。</p><p>这一切的前提是，你必须有一个如此强大的目标（因为你已经在里面投入了足够的能量），如果你没能实现它——感觉就像是早夭一样。</p><p>因此，当你决定出去玩、参加派对、多喝了几杯时……第二天你就会感觉到自己停滞不前。</p><p>你会生自己的气。</p><p>你会因为自己落后而感到有压力。</p><p>这就引出了我们的最后一点。</p><h2 id="情绪转化——将压力化为燃料" tabindex="-1">情绪转化——将压力化为燃料 <a class="header-anchor" href="#情绪转化——将压力化为燃料" aria-label="Permalink to &quot;情绪转化——将压力化为燃料&quot;">​</a></h2><p><em>唯一比追求最高版本的自己更痛苦的事，就是不追求最高版本的自己。</em></p><p>当你把自己投入到充满压力的情境中时，你就必须去应对伴随那种心理状态而来的负面情绪。</p><p>正是在这些时刻，你建立起了克服困境的心理韧性。</p><p>这种情绪负担要么成就你，要么摧毁你。</p><p>如果你能举起这重量并变得更强，你会惊讶于生活变得多么容易。那些能毁掉大多数人的小麻烦，根本不会让你动摇。</p><p>另一件事，后悔是生活中必不可少的一部分。</p><p>你无法避免它。</p><p>大多数人沉溺于后悔之中，就好像他们能改变过去一样。</p><p>你有两个选择：把它们看作让生活变得更糟的丑陋污点，或者把它们看作可以用未来更好的决定来弥合的裂缝。</p><p>在那些寻求改善生活的人身上，我注意到了一个规律。</p><p>维持现状的痛苦，必须超过在意他人眼光的痛苦。</p><p>人们会因为你做出了“愚蠢”的决定而认为你很愚蠢。</p><p>当你做出巨大改变时，人们会对你议论纷纷。</p><p>大多数时候，他们只是为了找乐子。</p><p>他们不理解你决定背后的信息。</p><p>随着时间的推移，你将学会无视他们。</p><p>另一个选择是什么？</p><p>因为别人说了你不喜欢的话，就让你的梦想被束之高阁慢慢死去？</p><p>那可真是让你最终泯然众人的绝佳方式。</p><p>—— Dan Koe</p><hr><p><a href="/en/letters/how-to-be-more-productive-than-99-of-people-how-to-get-out-of-a-rut">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',187))])}const w=o(h,[["render",c]]);export{_ as __pageData,w as default};
